/**
 * Redteam Sandbox Execution Manager.
 *
 * 管理 Docker Kali 容器沙箱与 SSH 远程隔离执行：
 * - 探测本地 Docker 与沙箱容器状态 (running, stopped, not_found, no_docker)
 * - 生成自动重定向到容器内部执行的 sandbox-shims (nmap, nuclei, fscan 等)
 * - 确保宿主机只保留 DSH 界面与日志交互，高危命令全部在沙箱容器内隔离执行
 */

import { execFileSync, spawnSync } from 'node:child_process'
import { existsSync, mkdirSync, writeFileSync } from 'node:fs'
import { homedir } from 'node:os'
import { join } from 'node:path'
import { redteamRoot, TOOL_CATALOG } from './platform-config.js'

export const DEFAULT_CONTAINER_NAME = 'dsh-kali-sandbox'

/** 沙箱 shims 脚本存放目录。 */
export function getSandboxShimsDir(root) {
  const base = root || redteamRoot()
  return join(base, 'sandbox-shims')
}

/** 探测本地 Docker 及沙箱容器运行状态。 */
export function inspectDockerSandbox(containerName = DEFAULT_CONTAINER_NAME) {
  const name = String(containerName || '').trim() || DEFAULT_CONTAINER_NAME
  try {
    const ver = execFileSync('docker', ['--version'], { encoding: 'utf8', timeout: 3000, stdio: ['ignore', 'pipe', 'ignore'] })
    const dockerVersion = String(ver || '').trim()
    try {
      const inspect = execFileSync('docker', ['inspect', '--format', '{{.State.Status}}', name], {
        encoding: 'utf8',
        timeout: 4000,
        stdio: ['ignore', 'pipe', 'ignore'],
      })
      const status = String(inspect || '').trim().toLowerCase()
      if (status === 'running') {
        return { ok: true, dockerInstalled: true, dockerVersion, container: name, running: true, status: 'running' }
      }
      return { ok: false, dockerInstalled: true, dockerVersion, container: name, running: false, status: status || 'stopped' }
    } catch {
      return { ok: false, dockerInstalled: true, dockerVersion, container: name, running: false, status: 'not_found' }
    }
  } catch {
    return { ok: false, dockerInstalled: false, container: name, running: false, status: 'no_docker' }
  }
}

/** 为全量 TOOL_CATALOG 工具生成容器代理 shims。 */
export function ensureSandboxShims(root, containerName = DEFAULT_CONTAINER_NAME) {
  const dir = getSandboxShimsDir(root)
  mkdirSync(dir, { recursive: true })
  const name = String(containerName || '').trim() || DEFAULT_CONTAINER_NAME
  const isWin = process.platform === 'win32'

  for (const tool of TOOL_CATALOG) {
    const cmdName = tool.names[tool.names.length - 1].replace(/\.exe$/i, '')
    const scriptPath = join(dir, cmdName)

    // POSIX shell shim
    const shContent = `#!/usr/bin/env bash
# Auto-generated by @deepseek-ai/dsh-purge (Docker Sandbox Proxy)
CONTAINER="\${DSH_SANDBOX_CONTAINER:-${name}}"
exec docker exec -i "$CONTAINER" ${cmdName} "$@"
`
    writeFileSync(scriptPath, shContent, { encoding: 'utf8', mode: 0o755 })

    // Windows CMD shim
    if (isWin) {
      const cmdPath = join(dir, `${cmdName}.cmd`)
      const cmdContent = `@echo off
set "CONTAINER=%DSH_SANDBOX_CONTAINER%"
if "%CONTAINER%"=="" set "CONTAINER=${name}"
docker exec -i %CONTAINER% ${cmdName} %*
`
      writeFileSync(cmdPath, cmdContent, { encoding: 'utf8' })
    }
  }

  return { ok: true, dir, count: TOOL_CATALOG.length }
}

/** 默认 Docker 启动命令。 */
export function getDockerLaunchCommand(containerName = DEFAULT_CONTAINER_NAME) {
  const name = String(containerName || '').trim() || DEFAULT_CONTAINER_NAME
  return `docker run -d --name ${name} --restart unless-stopped -v ~/.dsh/redteam:/root/.dsh/redteam -w /root/.dsh/redteam kalilinux/kali-rolling sleep infinity`
}
